style.css:
@-moz-document url-prefix("https://www.examtopics.com") {
body {
  background-color: #232731;
  color: #FFEFFF;
}

.card {
  background-color: #232731;
  color: #f4f4f4;
  border: 1px solid #f4f4f4;
}

.question-answer {
  color: #232731;
}

.card-title {
  color: #f4f4f4;
}

.examQa__date, .examQa__item span {
  color: #FFEFFF !important;
				}

.modal-content {
  background-color: #232731;
}

h1, h2, h3, h4, h5, h6 {
  color: #FFEFFF;
}
}
